export const DASHBOARD_CSS = "/* TipsUseLife AI Dashboard -- design tokens, then components.\n * U14 themes: data-theme picks the accent pair (indigo | ocean | sunset | grape),\n * data-mode picks light / dark / auto (system). Chart series (--s1..--s3) and\n * status colours (green / amber / red) never change with the theme. */\n:root, :root[data-theme=\"indigo\"] { --accent: #3A5BF5; --accent-2: #7C4DFF; --accent-d: #6E8BFF; --accent-2-d: #A98BFF; }\n:root[data-theme=\"ocean\"] { --accent: #0B7F99; --accent-2: #2563EB; --accent-d: #3CC3DE; --accent-2-d: #7AA7FF; }\n:root[data-theme=\"sunset\"] { --accent: #D63A50; --accent-2: #E57A1F; --accent-d: #FF7A8A; --accent-2-d: #FFB25C; }\n:root[data-theme=\"grape\"] { --accent: #7C3AED; --accent-2: #DB2777; --accent-d: #B38BFF; --accent-2-d: #FF7AB8; }\n:root {\n  --blue: var(--accent); --blue-dark: color-mix(in srgb, var(--accent) 80%, #000); --blue-soft: color-mix(in srgb, var(--accent) 11%, #fff);\n  --violet: var(--accent-2); --violet-soft: color-mix(in srgb, var(--accent-2) 11%, #fff);\n  --green: #12A150; --green-soft: #E5F7EC;\n  --amber: #C77700; --amber-soft: #FFF4E0;\n  --red: #D93636; --red-soft: #FDECEC;\n  --ink: #141B34; --ink-2: #39415C; --muted: #69728F; --muted-2: #8C94AD;\n  --line: #E7EAF3; --line-2: #D9DEEB; --bg: #F5F7FC; --card: #FFFFFF; --gray-soft: #F1F3F9; --hover: #F8F9FE;\n  --shadow: 0 1px 2px rgba(20, 27, 52, .04), 0 4px 16px rgba(20, 27, 52, .05);\n  --shadow-lg: 0 8px 28px rgba(20, 27, 52, .10);\n  --radius: 14px;\n  /* chart series: validated categorical slots 1-3 (dataviz validator) */\n  --s1: #2a78d6; --s2: #eb6834; --s3: #1baf7a;\n  color-scheme: light;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-mode=\"light\"]) {\n    --blue: var(--accent-d); --blue-dark: color-mix(in srgb, var(--accent-d) 78%, #fff); --blue-soft: color-mix(in srgb, var(--accent-d) 20%, #161B2F);\n    --violet: var(--accent-2-d); --violet-soft: color-mix(in srgb, var(--accent-2-d) 20%, #161B2F);\n    --green: #3DD181; --green-soft: #133524;\n    --amber: #F2B54B; --amber-soft: #3A2C10;\n    --red: #FF6B6B; --red-soft: #3D1A1D;\n    --ink: #E8EBF5; --ink-2: #C3C9DC; --muted: #9AA2BC; --muted-2: #7D85A0;\n    --line: #262C42; --line-2: #333A55; --bg: #0E1222; --card: #161B2F; --gray-soft: #1E2439; --hover: #1B2136;\n    --shadow: 0 1px 2px rgba(0, 0, 0, .3), 0 4px 16px rgba(0, 0, 0, .25);\n    --shadow-lg: 0 8px 28px rgba(0, 0, 0, .45);\n    --s1: #3987e5; --s2: #d95926; --s3: #199e70;\n    color-scheme: dark;\n  }\n}\n:root[data-mode=\"dark\"] {\n    --blue: var(--accent-d); --blue-dark: color-mix(in srgb, var(--accent-d) 78%, #fff); --blue-soft: color-mix(in srgb, var(--accent-d) 20%, #161B2F);\n    --violet: var(--accent-2-d); --violet-soft: color-mix(in srgb, var(--accent-2-d) 20%, #161B2F);\n    --green: #3DD181; --green-soft: #133524;\n    --amber: #F2B54B; --amber-soft: #3A2C10;\n    --red: #FF6B6B; --red-soft: #3D1A1D;\n    --ink: #E8EBF5; --ink-2: #C3C9DC; --muted: #9AA2BC; --muted-2: #7D85A0;\n    --line: #262C42; --line-2: #333A55; --bg: #0E1222; --card: #161B2F; --gray-soft: #1E2439; --hover: #1B2136;\n    --shadow: 0 1px 2px rgba(0, 0, 0, .3), 0 4px 16px rgba(0, 0, 0, .25);\n    --shadow-lg: 0 8px 28px rgba(0, 0, 0, .45);\n    --s1: #3987e5; --s2: #d95926; --s3: #199e70;\n    color-scheme: dark;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--bg); color: var(--ink); font: 14px/1.55 \"IBM Plex Sans Thai\", system-ui, -apple-system, \"Segoe UI\", sans-serif; -webkit-font-smoothing: antialiased; }\n.mono { font-family: \"IBM Plex Mono\", ui-monospace, monospace; }\n.small { font-size: 12px; } .muted { color: var(--muted); } .nowrap { white-space: nowrap; }\n.error { color: var(--red); margin: 6px 0 0; } .pre { white-space: pre-wrap; word-break: break-word; }\nh2 { font-size: 22px; margin: 4px 0 14px; letter-spacing: -.01em; } h3 { font-size: 15px; margin: 22px 0 10px; color: var(--ink-2); }\na { color: var(--blue); text-decoration: none; } a:hover { text-decoration: underline; }\na.plink { color: var(--ink); border-bottom: 1px dashed var(--muted-2); } a.plink:hover { color: var(--blue); text-decoration: none; border-bottom-color: var(--blue); }\n.icon { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex: none; }\n.icon.sm { width: 14px; height: 14px; vertical-align: -2px; }\n\n/* ---------- shell ---------- */\n.topbar { position: sticky; top: 0; z-index: 20; background: color-mix(in srgb, var(--card) 88%, transparent); backdrop-filter: saturate(180%) blur(10px); border-bottom: 1px solid var(--line); }\n.topbar-inner { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; max-width: 1240px; margin: 0 auto; padding: 12px 24px 6px; }\n.topbar-right { display: flex; gap: 10px; align-items: center; }\n.brand { display: flex; align-items: center; gap: 10px; color: var(--ink); } .brand:hover { text-decoration: none; }\n.logo { width: 36px; height: 36px; border-radius: 11px; background: linear-gradient(135deg, var(--blue), var(--violet)); color: #fff; display: grid; place-items: center; font-weight: 700; box-shadow: 0 4px 12px rgba(58, 91, 245, .35); }\n.tabs { display: flex; gap: 4px; max-width: 1240px; margin: 0 auto; padding: 4px 24px 10px; overflow-x: auto; scrollbar-width: none; }\n.tab { padding: 7px 14px; border-radius: 999px; color: var(--muted); white-space: nowrap; font-weight: 500; transition: background .15s, color .15s; }\n.tab:hover { background: var(--gray-soft); color: var(--ink); text-decoration: none; }\n.tab.active { background: var(--blue-soft); color: var(--blue); font-weight: 600; }\nmain { padding: 22px 24px 64px; max-width: 1240px; margin: 0 auto; }\n\n/* ---------- cards & generic ---------- */\n.card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px 20px; margin-bottom: 16px; box-shadow: var(--shadow); }\n.card-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 12px; flex-wrap: wrap; }\n.card-head h3 { margin: 0; color: var(--ink); font-size: 16px; }\n.link-more { display: inline-flex; align-items: center; gap: 4px; font-weight: 600; font-size: 13px; }\n.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 12px; }\n.tile { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; }\n.tile-value { font-size: 24px; font-weight: 700; } .tile-label { color: var(--muted); font-size: 12px; }\n\n/* ---------- overview ---------- */\n.hero { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; margin-bottom: 18px; }\n.hero h2 { font-size: 26px; margin: 0 0 2px; } .hero p { margin: 0; }\n.hero-actions { display: flex; gap: 10px; align-items: center; }\n.kpi-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin-bottom: 16px; }\n.kpi { display: flex; gap: 14px; align-items: flex-start; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow); color: var(--ink); transition: transform .15s, box-shadow .15s, border-color .15s; }\n.kpi:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); border-color: var(--line-2); text-decoration: none; }\n.kpi-icon { width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; flex: none; }\n.kpi-icon .icon { width: 21px; height: 21px; }\n.kpi-label { color: var(--muted); font-size: 13px; font-weight: 500; }\n.kpi-value { font-size: 30px; font-weight: 700; line-height: 1.15; letter-spacing: -.02em; margin: 2px 0; }\n.kpi-sub { color: var(--muted-2); font-size: 12px; }\n.tone-blue .kpi-icon { background: var(--blue-soft); color: var(--blue); }\n.tone-violet .kpi-icon { background: var(--violet-soft); color: var(--violet); }\n.tone-green .kpi-icon { background: var(--green-soft); color: var(--green); }\n.tone-red .kpi-icon { background: var(--red-soft); color: var(--red); }\n.tone-gray .kpi-icon { background: var(--gray-soft); color: var(--muted); }\n.kpi.tone-red { border-color: color-mix(in srgb, var(--red) 35%, var(--line)); }\n.kpi.tone-red .kpi-value { color: var(--red); }\n.ov-grid { display: grid; grid-template-columns: 3fr 2fr; gap: 16px; }\n.funnel { display: grid; gap: 12px; }\n.funnel-label { display: flex; justify-content: space-between; gap: 8px; font-size: 13px; margin-bottom: 5px; }\n.funnel-num { color: var(--muted); font-variant-numeric: tabular-nums; }\n.bar { display: block; height: 8px; background: var(--gray-soft); border-radius: 999px; overflow: hidden; }\n.bar-fill { display: block; height: 100%; border-radius: 999px; width: 0; transition: width .5s ease; }\n.bar-fill.tone-blue { background: var(--blue); } .bar-fill.tone-violet { background: var(--violet); }\n.bar-fill.tone-green { background: var(--green); } .bar-fill.tone-amber { background: var(--amber); }\n.mini-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin-top: 16px; }\n.mini { display: flex; flex-direction: column; padding: 10px 12px; border-radius: 10px; background: var(--gray-soft); color: var(--ink); transition: background .15s; }\n.mini:hover { background: var(--hover); text-decoration: none; outline: 1px solid var(--line-2); }\n.mini-value { font-size: 18px; font-weight: 700; } .mini-label { font-size: 11.5px; color: var(--muted); line-height: 1.35; }\n.mini.tone-amber { background: var(--amber-soft); } .mini.tone-amber .mini-value { color: var(--amber); }\n.meter { display: block; color: var(--ink); padding: 10px 0 12px; border-bottom: 1px solid var(--line); }\n.meter:hover { text-decoration: none; } .meter:hover .meter-head span { color: var(--blue); }\n.meter-head { display: flex; justify-content: space-between; margin-bottom: 6px; font-size: 13px; }\n.meter .muted { margin-top: 4px; }\n.quick { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }\n.quick .btn { margin: 0; }\n.health-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; margin-bottom: 14px; }\n.health { border-radius: 12px; padding: 12px 14px; background: var(--gray-soft); border: 1px solid transparent; }\n.health-value { font-size: 20px; font-weight: 700; font-variant-numeric: tabular-nums; } .health-label { font-size: 12px; color: var(--muted); }\n.health.tone-ok .health-value { color: var(--ink-2); }\n.health.tone-green { background: var(--green-soft); } .health.tone-green .health-value { color: var(--green); }\n.health.tone-amber { background: var(--amber-soft); border-color: color-mix(in srgb, var(--amber) 30%, transparent); } .health.tone-amber .health-value { color: var(--amber); }\n.health.tone-red { background: var(--red-soft); border-color: color-mix(in srgb, var(--red) 30%, transparent); } .health.tone-red .health-value { color: var(--red); }\n.ok-line { display: flex; align-items: center; gap: 4px; color: var(--green); margin: 0; }\n.feed { list-style: none; margin: 0; padding: 0; }\n.feed-item { display: flex; gap: 12px; padding: 14px 0; border-top: 1px solid var(--line); }\n.feed-item:first-child { border-top: 0; padding-top: 4px; }\n.avatar { width: 36px; height: 36px; border-radius: 50%; background: linear-gradient(135deg, var(--blue-soft), var(--violet-soft)); color: var(--blue); display: grid; place-items: center; font-weight: 700; flex: none; }\n.feed-body { min-width: 0; flex: 1; }\n.feed-top { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n.feed-text { margin: 3px 0; word-break: break-word; }\n.feed-reply { display: flex; gap: 6px; align-items: flex-start; background: var(--gray-soft); border-radius: 10px; padding: 8px 10px; margin: 6px 0; color: var(--ink-2); font-size: 13px; }\n.feed-reply .icon { margin-top: 3px; color: var(--blue); }\n.feed-links { display: flex; gap: 14px; flex-wrap: wrap; align-items: center; margin-top: 4px; }\n.links { display: inline-flex; gap: 12px; flex-wrap: wrap; } td .links { margin-top: 4px; }\n\n/* ---------- tables ---------- */\ntable { width: 100%; border-collapse: separate; border-spacing: 0; background: var(--card); border: 1px solid var(--line); border-radius: 12px; overflow: hidden; box-shadow: var(--shadow); }\nth, td { text-align: left; padding: 11px 14px; border-bottom: 1px solid var(--line); vertical-align: top; }\ntbody tr:last-child td { border-bottom: 0; }\ntbody tr { transition: background .12s; } tbody tr:hover { background: var(--hover); }\nth { background: var(--gray-soft); color: var(--muted); font-weight: 600; font-size: 12px; text-transform: none; letter-spacing: .01em; }\ntd.reply { max-width: 320px; }\ntable.kv { box-shadow: none; } table.kv th { width: 260px; background: none; color: var(--ink-2); }\n.card table { box-shadow: none; }\n\n/* ---------- pagination ---------- */\n.paged { display: grid; gap: 0; }\n.pager { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin: 12px 0 4px; }\n.pg-info { color: var(--muted); font-size: 12.5px; font-variant-numeric: tabular-nums; }\n.pg-nav { display: flex; gap: 4px; align-items: center; flex-wrap: wrap; }\n.pg-btn { min-width: 34px; height: 34px; padding: 0 10px; border-radius: 9px; border: 1px solid var(--line-2); background: var(--card); color: var(--ink); font: inherit; cursor: pointer; font-variant-numeric: tabular-nums; }\n.pg-btn:hover:not([disabled]) { border-color: var(--blue); color: var(--blue); }\n.pg-btn.active { background: var(--blue); border-color: var(--blue); color: #fff; font-weight: 600; }\n.pg-btn[disabled] { opacity: .4; cursor: default; }\n.pg-gap { color: var(--muted-2); padding: 0 4px; } .pg-current { padding: 0 10px; font-weight: 600; font-size: 13px; }\nselect.page-size { width: auto; padding: 6px 8px; font-size: 12.5px; }\n\n/* ---------- badges & buttons ---------- */\n.badge { display: inline-flex; align-items: center; gap: 5px; padding: 2px 9px; border-radius: 999px; font-size: 11px; font-weight: 600; background: var(--gray-soft); color: var(--ink-2); margin: 1px 0; white-space: nowrap; }\n.badge.blue { background: var(--blue-soft); color: var(--blue); } .badge.green { background: var(--green-soft); color: var(--green); }\n.badge.red { background: var(--red-soft); color: var(--red); } .badge.gray { background: var(--gray-soft); color: var(--muted); }\n.badge.mode { padding: 5px 12px; font-size: 12px; }\n.badge .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }\n.badge.live .dot { animation: pulse 1.8s ease-out infinite; }\n@keyframes pulse { 0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--red) 55%, transparent); } 100% { box-shadow: 0 0 0 7px transparent; } }\n@media (prefers-reduced-motion: reduce) { .badge.live .dot { animation: none; } .kpi, .bar-fill { transition: none; } }\n.btn { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--line-2); background: var(--card); color: var(--ink); padding: 8px 14px; border-radius: 10px; font: inherit; font-weight: 500; cursor: pointer; transition: border-color .15s, background .15s, color .15s; }\na.btn:hover { text-decoration: none; }\n.btn:hover { border-color: var(--blue); color: var(--blue); } .btn.primary { background: var(--blue); border-color: var(--blue); color: #fff; box-shadow: 0 2px 8px rgba(58, 91, 245, .25); }\n.btn.primary:hover { background: var(--blue-dark); color: #fff; } .btn.ghost { background: transparent; }\n.btn[disabled] { opacity: .55; cursor: default; }\n.btn.danger { color: var(--red); } .btn.danger:hover { border-color: var(--red); background: var(--red-soft); }\n.btn.small { padding: 4px 10px; font-size: 12px; margin-right: 4px; border-radius: 8px; }\n\n/* ---------- forms ---------- */\ninput, select, textarea { font: inherit; padding: 8px 11px; border: 1px solid var(--line-2); border-radius: 10px; background: var(--card); color: var(--ink); width: 100%; transition: border-color .15s, box-shadow .15s; }\ninput:focus, select:focus, textarea:focus { outline: none; border-color: var(--blue); box-shadow: 0 0 0 3px var(--blue-soft); }\na:focus-visible, button:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }\ninput[type=checkbox] { width: auto; accent-color: var(--blue); }\n.field { margin-bottom: 12px; } .field label { display: block; font-size: 12px; color: var(--ink-2); margin-bottom: 4px; font-weight: 600; }\n.hint { font-size: 12px; color: var(--muted-2); margin-top: 3px; }\n.form { max-width: 640px; } .form.inline { max-width: none; display: grid; grid-template-columns: 2fr 1fr 2fr 2fr auto; gap: 12px; align-items: end; }\n.form.inline .field { margin: 0; } .actions { display: flex; gap: 8px; margin-top: 8px; }\n.check { display: flex; gap: 8px; align-items: center; margin: 8px 0; }\n.switch { display: inline-flex; gap: 6px; align-items: center; cursor: pointer; }\n.toolbar { display: flex; gap: 10px; margin-bottom: 14px; flex-wrap: wrap; } .toolbar .search { max-width: 320px; } .toolbar select { max-width: 180px; }\n.row-between { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 4px; }\n.row-between select { max-width: 200px; }\n.thumb { width: 42px; height: 42px; border-radius: 10px; object-fit: cover; background: var(--gray-soft); display: block; }\n.login { min-height: 100vh; display: grid; place-items: center; padding: 16px; background: radial-gradient(1200px 600px at 10% -10%, var(--blue-soft), transparent), radial-gradient(900px 500px at 110% 110%, var(--violet-soft), transparent); }\n.login-card { width: 100%; max-width: 380px; display: grid; gap: 10px; padding: 26px; box-shadow: var(--shadow-lg); }\n.note p { color: var(--ink-2); }\n.toast { position: fixed; bottom: 20px; right: 20px; background: var(--ink); color: var(--card); padding: 11px 16px; border-radius: 12px; opacity: 0; transform: translateY(8px); transition: opacity .2s, transform .2s; pointer-events: none; max-width: 360px; box-shadow: var(--shadow-lg); z-index: 50; }\n.toast.show { opacity: 1; transform: none; } .toast.err { background: var(--red); color: #fff; }\n\n/* ---------- trend chart (U3) ---------- */\n.head-tools { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n.seg { display: inline-flex; background: var(--gray-soft); border-radius: 10px; padding: 3px; gap: 2px; }\n.seg-btn { border: 0; background: transparent; color: var(--muted); font: inherit; font-size: 12.5px; padding: 5px 11px; border-radius: 8px; cursor: pointer; }\n.seg-btn.active { background: var(--card); color: var(--ink); font-weight: 600; box-shadow: var(--shadow); }\n.trend-body { transition: opacity .2s; } .trend-body.loading { opacity: .55; }\n.legend { display: flex; gap: 16px; flex-wrap: wrap; margin: 4px 0 8px; font-size: 12.5px; color: var(--ink-2); }\n.legend-item { display: inline-flex; align-items: center; gap: 6px; }\n.legend-key { width: 16px; height: 2px; border-radius: 2px; background: currentColor; display: inline-block; }\n.legend-key.s1, .tip-key.s1 { color: var(--s1); } .legend-key.s2, .tip-key.s2 { color: var(--s2); } .legend-key.s3, .tip-key.s3 { color: var(--s3); }\n.chart-wrap { position: relative; outline: none; border-radius: 10px; }\n.chart-wrap:focus-visible { box-shadow: 0 0 0 2px var(--blue); }\nsvg.trend { width: 100%; height: auto; display: block; overflow: visible; }\nsvg.trend .grid { stroke: var(--line); stroke-width: 1; }\nsvg.trend .axis { stroke: var(--line-2); stroke-width: 1; }\nsvg.trend .tick { fill: var(--muted-2); font-size: 11px; font-family: inherit; }\nsvg.trend .end-label { fill: var(--ink-2); font-size: 11px; font-weight: 600; font-family: inherit; }\nsvg.trend .line { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }\nsvg.trend .line.s1, svg.trend .key.s1 { stroke: var(--s1); } svg.trend .line.s2, svg.trend .key.s2 { stroke: var(--s2); } svg.trend .line.s3, svg.trend .key.s3 { stroke: var(--s3); }\nsvg.trend .key { stroke-width: 2; stroke-linecap: round; }\nsvg.trend .hair { stroke: var(--muted-2); stroke-width: 1; stroke-dasharray: 3 3; }\nsvg.trend .dot { stroke: var(--card); stroke-width: 2; }\nsvg.trend .dot.s1 { fill: var(--s1); } svg.trend .dot.s2 { fill: var(--s2); } svg.trend .dot.s3 { fill: var(--s3); }\nsvg.trend .hit { fill: transparent; cursor: crosshair; }\n.chart-tip { position: absolute; top: 6px; left: 0; min-width: 160px; background: var(--card); border: 1px solid var(--line-2); border-radius: 10px; box-shadow: var(--shadow-lg); padding: 8px 10px; font-size: 12px; pointer-events: none; opacity: 0; transition: opacity .12s; }\n.chart-tip.show { opacity: 1; }\n.tip-day { font-weight: 600; margin-bottom: 4px; color: var(--ink); }\n.tip-row { display: flex; align-items: center; gap: 6px; line-height: 1.7; }\n.tip-row strong { min-width: 28px; text-align: right; font-variant-numeric: tabular-nums; }\n.tip-key { width: 12px; height: 2px; border-radius: 2px; background: currentColor; display: inline-block; } .tip-key.none { background: transparent; }\ntable.compact th, table.compact td { padding: 6px 10px; }\ntd.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }\n\n/* ---------- activity search (U4) + clickable rows ---------- */\n.toolbar.filters { align-items: center; } .toolbar.filters .search { flex: 1 1 240px; }\n.toolbar.filters input[type=date] { width: auto; }\n.toolbar.filters input.mono { max-width: 230px; }\n.inline-field { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--muted); white-space: nowrap; }\ntr.clickable, li.clickable { cursor: pointer; }\nli.clickable:hover { background: var(--hover); border-radius: 10px; }\ntr.clickable:focus-visible, li.clickable:focus-visible { outline: 2px solid var(--blue); outline-offset: -2px; }\n\n/* ---------- comment drawer (U6) ---------- */\n.drawer { position: fixed; inset: 0; z-index: 40; }\n.drawer-scrim { position: absolute; inset: 0; background: rgba(10, 14, 30, .35); animation: fade .15s ease; }\n.drawer-panel { position: absolute; top: 0; right: 0; bottom: 0; width: min(520px, 100%); background: var(--card); border-left: 1px solid var(--line); box-shadow: var(--shadow-lg); padding: 18px 20px 40px; overflow-y: auto; outline: none; animation: slide .18s ease; }\n.drawer-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }\n.drawer-head h3 { margin: 0; color: var(--ink); font-size: 17px; }\n.quote { background: var(--gray-soft); border-radius: 10px; padding: 10px 12px; margin: 10px 0; }\n.dkv { display: grid; grid-template-columns: 130px 1fr; gap: 8px; padding: 7px 0; border-bottom: 1px solid var(--line); font-size: 13px; }\n.dk { color: var(--muted); }\n.timeline { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }\n.timeline li { border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; }\n.reply-text { margin: 6px 0; font-size: 13px; }\ndetails summary { cursor: pointer; color: var(--muted); font-size: 12.5px; margin-top: 12px; }\n.raw { background: var(--gray-soft); border-radius: 8px; padding: 8px; margin-top: 6px; max-height: 240px; overflow: auto; }\n@keyframes slide { from { transform: translateX(24px); opacity: 0; } to { transform: none; opacity: 1; } }\n@keyframes fade { from { opacity: 0; } to { opacity: 1; } }\n@media (prefers-reduced-motion: reduce) { .drawer-panel, .drawer-scrim { animation: none; } }\n\n/* ---------- audit (U8) ---------- */\n.chg { line-height: 1.6; word-break: break-word; }\n\n/* ---------- settings sub-tabs + theme picker (U14) ---------- */\n.subtabs { display: flex; gap: 4px; border-bottom: 1px solid var(--line); margin: 0 0 16px; overflow-x: auto; scrollbar-width: none; }\n.subtab { border: 0; background: none; font: inherit; color: var(--muted); padding: 9px 14px; cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; white-space: nowrap; }\n.subtab:hover { color: var(--ink); }\n.subtab.active { color: var(--blue); border-bottom-color: var(--blue); font-weight: 600; }\n.theme-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; }\n.theme-opt { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--card); color: var(--ink); font: inherit; cursor: pointer; text-align: left; }\n.theme-opt:hover { border-color: var(--blue); }\n.theme-opt.active { border-color: var(--blue); box-shadow: 0 0 0 3px var(--blue-soft); }\n.theme-swatch { width: 28px; height: 28px; border-radius: 8px; flex: none; }\n.theme-name { flex: 1; font-weight: 600; }\n.theme-check { color: var(--blue); font-weight: 700; }\n\n/* ---------- suggestion decisions (U14) ---------- */\n.decision { margin-top: 4px; line-height: 1.5; }\n.via-auto { color: var(--violet); font-weight: 600; }\n.via-human { color: var(--ink-2); font-weight: 600; }\n.ok-text { color: var(--green); }\n\n@media (max-width: 1000px) {\n  .kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .ov-grid { grid-template-columns: 1fr; }\n}\n@media (max-width: 760px) {\n  .chart-wrap { overflow-x: auto; } svg.trend { min-width: 600px; }\n  main { padding: 16px; } .form.inline { grid-template-columns: 1fr; }\n  table { display: block; overflow-x: auto; } th, td { min-width: 120px; }\n  .topbar-inner, .tabs { padding-left: 16px; padding-right: 16px; }\n  .mini-row { grid-template-columns: 1fr; }\n  .kpi-value { font-size: 26px; }\n}\n@media (max-width: 420px) { .kpi-grid { grid-template-columns: 1fr; } }\n";
